function settingsPage(){return heading('DEPLOYMENT & GOVERNANCE / 09','部署与维护','服务器独立部署，数据由你管理；先确认环境，再接入真实业务。',button(icon('download')+'导出 JSON','export'))+`<div class="integrate-grid"><section class="panel"><div class="panel-head"><h2>当前运行环境</h2><span class="badge ${DEMO?'orange':'green'}">${DEMO?'本机体验':'服务器模式'}</span></div><dl class="kv"><dt>应用版本</dt><dd>0.3.0 · schema 1</dd><dt>数据保存</dt><dd>${DEMO?'仅当前浏览器 localStorage；不会自动同步到服务器':'服务器 SQLite；请定期执行完整备份'}</dd><dt>当前身份</dt><dd>${esc(user?.name||'演示用户')} / ${esc(user?.role||'demo')}</dd><dt>执行权限</dt><dd>不执行远程命令、真机调度或代码发布</dd><dt>审核性质</dt><dd>${DEMO?'本机演示；不能作为独立审核凭证':'人工独立审核记录；不等于自动评测，也不对外部证据真实性做自动证明'}</dd></dl><div class="card-divider"></div><div class="row wrap">${(DEMO||user?.role==='admin')?button(icon('upload')+'导入 JSON','import'):''}${DEMO?button(icon('refresh')+'重置本机示例','reset','','danger'):button(icon('logout')+'退出登录','logout','','ghost')}${button(icon('export')+'打印当前页面','print','','ghost')}</div><p class="muted tiny">${DEMO?'导入会替换当前本机数据，操作前建议导出。':'服务器导入新增草稿副本，不覆盖既有节点，不继承审核结论；完整灾备请用数据库备份。'}</p><input type="file" accept="application/json,.json" id="import-file" hidden></section><section class="panel"><h2>部署前需要确认</h2><div class="numbered"><b>1</b><div><h3>运行环境</h3><p>云厂商 / 内网或公网、Linux 发行版、CPU 架构、Docker / Compose、现有网站和占用端口。</p></div></div><div class="numbered"><b>2</b><div><h3>访问与域名</h3><p>子域名、HTTPS、访问人员；个人服务器是否获准承载工作数据。尚未批准时只放蓝图与脱敏示例。</p></div></div><div class="numbered"><b>3</b><div><h3>部署执行途径</h3><p>通过受信任的远程部署环境或服务器本地终端操作。不要在聊天中发送 root 密码、私钥和云主账号密钥。</p></div></div></section></div><section class="panel mt20"><div class="panel-head"><h2>最近操作记录</h2><span class="muted tiny">${DEMO?'本机可修改记录，不具备安全审计效力':'应用接口只追加；数据库管理员仍可修改，不是防篡改审计系统'}</span></div>${state.audit?.length?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>执行者</th><th>操作</th><th>对象</th><th>说明</th></tr></thead><tbody>${state.audit.slice(0,30).map(a=>`<tr><td>${fmtTime(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.kind)}</td><td class="table-sub">${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无操作记录','修改节点或创建任务后，这里会留下操作记录。')}</section>`;}
function renderPage(){if(!state)return;stopTour();route=routeNames[location.hash.slice(1)]?location.hash.slice(1):'overview';$$('.nav-link').forEach(el=>el.classList.toggle('active',el.dataset.route===route));if($('#breadcrumb-current'))$('#breadcrumb-current').textContent=routeNames[route];const pages={overview,requirements:requirementsPage,tasks:tasksPage,experiments:experimentsPage,evolutions:evolutionPage,feedback:feedbackPage,capabilities:capabilitiesPage,integrations:integrationsPage,roadmap:roadmapPage,settings:settingsPage};if($('#search')){$('#search').disabled=!['overview','tasks','experiments','evolutions','feedback','capabilities'].includes(route);$('#search').placeholder=$('#search').disabled?'此页不含可搜索记录':'搜索当前页面…';}$('#page').innerHTML=pages[route]()+`<footer class="site-footer"><span>GamePerf Studio · 可维护架构 · 可追溯证据 · 受控演进</span><span>${DEMO?'LOCAL PREVIEW / 示例数据 · 无真实设备连接':'证据先行 · 权限隔离 · 持续迭代'}</span></footer>`;if($('#import-file'))$('#import-file').addEventListener('change',onImport);}
